import math
def brute(n):
    best = 1
    for a in range(1, n):
        for b in range(a+1, n+1):
            g = math.gcd(a, b)
            if g > best:
                best = g
    return best

for n in range(2, 101):
    expected = n // 2
    actual = brute(n)
    if expected != actual:
        print(f'Mismatch at n={n}: expected {expected}, actual {actual}')
        break
else:
