# random larger n
import random
random.seed(42)
for _ in range(20):
    n = random.randint(1000, 2000)
    # compute using formula
    expected = n // 2
    # compute using smarter method: max gcd is floor(n/2) indeed
    # we can compute by checking multiples
    actual = 0
    for g in range(n//2, 0, -1):
        # check if there exist two distinct multiples of g <= n
        # the largest multiple is (n // g) * g
        # need at least two multiples, i.e., n // g >= 2
        if (n // g) >= 2:
            actual = g
            break
    if expected != actual:
        print(f'Large mismatch n={n}: expected {expected}, actual {actual}')
        break
else:
    print('Random large n match.')
