    """Return the encoded string of word positions."""
    words = sentence.split()
    mapping = {}
    result = []
    idx = 0
    for w in words:
        lower = w.lower()
        if lower not in mapping:
            mapping[lower] = idx
            idx += 1
        result.append(str(mapping[lower]))
    return ''.join(result)

