import sys
import math

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    K = int(data)
    total = 0
    for a in range(1, K+1):
        for b in range(1, K+1):
            g = math.gcd(a, b)
            for c in range(1, K+1):
                total += math.gcd(g, c)
    print(total)

if __name__ == "__main__":
    main()
