import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    seq = list(map(int, data[1:]))
    on_table = set()
    max_count = 0
    for x in seq:
        if x in on_table:
            on_table.remove(x)
        else:
            on_table.add(x)
        max_count = max(max_count, len(on_table))
    print(max_count)

if __name__ == "__main__":
